import { Effect, FileSystem, Path } from "effect"
import { NodeRuntime, NodeServices } from "@effect/platform-node"

/* The generated module: both Markdown files as string constants. */
const render = (template: string, policy: string): string =>
    [
      "// Generated by scripts/vendor-codex-policy.ts. Do not edit.",
      "// Source: the Markdown files beside this one; see UPSTREAM.md.",
      "",
      `const POLICY = ${JSON.stringify(policy)},`,
      `  POLICY_TEMPLATE = ${JSON.stringify(template)}`,
      "",
      "/** The vendored Codex Auto-review policy and its template. */",
      "export default Object.freeze({ POLICY, POLICY_TEMPLATE })",
      "",
    ].join("\n"),
  /* Regenerates `policy.ts` from the Markdown files beside it. */
  vendorPolicy = Effect.gen(function* vendorPolicy() {
    const fs = yield* FileSystem.FileSystem,
      path = yield* Path.Path,
      vendored = path.join(import.meta.dirname, "..", "src", "vendor", "codex"),
      [template, policy] = yield* Effect.all(
        [
          fs.readFileString(path.join(vendored, "policy_template.md")),
          fs.readFileString(path.join(vendored, "policy.md")),
        ],
        { concurrency: "unbounded" },
      )

    yield* fs.writeFileString(
      path.join(vendored, "policy.ts"),
      render(template, policy),
    )
  })

NodeRuntime.runMain(vendorPolicy.pipe(Effect.provide(NodeServices.layer)))
